import glob,re,datetime
today=datetime.date(2026,6,1)
def fm(p):
    t=open(p,encoding='utf-8').read()
    m=re.match(r'^---\n(.*?)\n---',t,re.S)
    d={}
    if m:
        for line in m.group(1).splitlines():
            mm=re.match(r'^(\w+):\s*(.*)$',line)
            if mm: d[mm.group(1)]=mm.group(2).strip().strip('"')
    return d
print("== ACTIVE files with a parseable deadline date in the PAST ==")
for p in sorted(glob.glob("*.md")):
    d=fm(p)
    dl=d.get("deadline","")
    status=d.get("status","")
    m=re.search(r'(\d{4})-(\d{2})-(\d{2})',dl)
    if m:
        dd=datetime.date(int(m.group(1)),int(m.group(2)),int(m.group(3)))
        if dd<today:
            print(f"EXPIRED {dd} status={status:8} | {p}")
print("== files with status != active ==")
for p in sorted(glob.glob("*.md")):
    d=fm(p)
    if d.get("status")!="active":
        print(f"  status={d.get('status')} | {p}")
print("== total active md files ==", sum(1 for p in glob.glob("*.md") if fm(p).get("status")=="active"))
